
-- Create internal links table
CREATE TABLE IF NOT EXISTS blog_post_links (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  source_slug TEXT NOT NULL,
  target_slug TEXT NOT NULL,
  link_type TEXT DEFAULT 'contextual', -- pillar, primary, secondary, contextual
  position INT DEFAULT 1,
  anchor_text TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  UNIQUE(source_slug, target_slug),
  FOREIGN KEY (source_slug) REFERENCES blog_posts(slug) ON DELETE CASCADE,
  FOREIGN KEY (target_slug) REFERENCES blog_posts(slug) ON DELETE CASCADE
);

CREATE INDEX idx_blog_post_links_source ON blog_post_links(source_slug);
CREATE INDEX idx_blog_post_links_target ON blog_post_links(target_slug);
CREATE INDEX idx_blog_post_links_type ON blog_post_links(link_type);



-- Upsert blog post links (idempotent)
ON CONFLICT (source_slug, target_slug)
DO UPDATE SET
  link_type = EXCLUDED.link_type,
  position = EXCLUDED.position,
  updated_at = NOW();
